
      #root {
        min-height: 100vh
      }

      @keyframes loading-indicator-kf {
        0% {
          animation-timing-function: cubic-bezier(1, 0, 0.7, 1);
          opacity: 0.5;
          transform: scale(1)
        }

        40% {
          animation-timing-function: cubic-bezier(0.3, 0, 0, 1);
          opacity: 0.75;
          transform: scale(1.3)
        }

        72.5% {
          animation-timing-function: linear;
          opacity: 0.5;
          transform: scale(1)
        }

        100% {
          opacity: 0.5;
          transform: scale(1)
        }
      }

